import math

def check_condition(n):
    if n < 2:
        return False

    # Find all integers k in [1, n-1] such that gcd(k, n) = 1
    coprimes = [k for k in range(1, n) if math.gcd(k, n) == 1]

    # Check if k^2 - 1 is a multiple of n for all such k
    for k in coprimes:
        if (k**2 - 1) % n != 0:
            return False
    return True

print(f"Does n=24 satisfy the condition? {check_condition(24)}")
print(f"Does n=16 satisfy the condition? {check_condition(16)}")

import math

candidates = [2, 3, 4, 6, 8, 12, 24]
results = {}

def check_n(n):
    for k in range(1, n):
        if math.gcd(k, n) == 1:
            # Check k^2 == 1 (mod n)
            if (k * k) % n != 1:
                return False, k
    return True, None

for n in candidates:
    is_solution, counterexample_k = check_n(n)
    results[n] = is_solution

print("--- Verification Results ---")
for n, is_solution in results.items():
    status = "Satisfies" if is_solution else "Fails"
    if not is_solution:
        print(f"n={n}: {status} (Fails for k={counterexample_k})")
    else:
        print(f"n={n}: {status}")
